const lessons=[{"sentences":[{"speaker":"A","text":"Hello I am sorry to bother you so late tonight.","position":1,"audioStartSeconds":0,"audioEndSeconds":3.523041666666667},{"speaker":"B","text":"Hello Mark is everything alright with your flat upstairs?","position":2,"audioStartSeconds":3.7230416666666666,"audioEndSeconds":7.632666666666666},{"speaker":"A","text":"Well actually your television is quite loud through my bedroom ceiling.","position":3,"audioStartSeconds":7.832666666666666,"audioEndSeconds":12.305083333333334},{"speaker":"B","text":"Oh dear I did not realize the volume was up so high.","position":4,"audioStartSeconds":12.505083333333333,"audioEndSeconds":16.397625},{"speaker":"A","text":"I have an early meeting tomorrow morning because of an important project.","position":5,"audioStartSeconds":16.597625,"audioEndSeconds":21.107958333333332},{"speaker":"B","text":"I completely understand why you need to sleep now.","position":6,"audioStartSeconds":21.307958333333332,"audioEndSeconds":24.877541666666666},{"speaker":"A","text":"Thank you for being so understanding about this annoying situation.","position":7,"audioStartSeconds":25.077541666666665,"audioEndSeconds":29.420291666666667},{"speaker":"B","text":"I will turn the sound down immediately so you can rest.","position":8,"audioStartSeconds":29.620291666666667,"audioEndSeconds":33.43470833333333},{"speaker":"A","text":"That would be wonderful and I really appreciate your quick help.","position":9,"audioStartSeconds":33.634708333333336,"audioEndSeconds":37.681125},{"speaker":"B","text":"Would you like me to wear wireless headphones after nine pm?","position":10,"audioStartSeconds":37.881125,"audioEndSeconds":41.81154166666666},{"speaker":"A","text":"That is a brilliant idea which would solve the problem permanently.","position":11,"audioStartSeconds":42.011541666666666,"audioEndSeconds":46.186791666666664},{"speaker":"B","text":"I bought a pair last week but I simply forgot to use them.","position":12,"audioStartSeconds":46.38679166666667,"audioEndSeconds":50.18833333333333},{"speaker":"A","text":"Wireless headphones are fantastic for watching action movies late at night.","position":13,"audioStartSeconds":50.388333333333335,"audioEndSeconds":55.40120833333334},{"speaker":"B","text":"I will charge them tonight and use them every single evening.","position":14,"audioStartSeconds":55.60120833333333,"audioEndSeconds":59.48008333333333},{"speaker":"A","text":"Have a wonderful rest of your evening and goodnight.","position":15,"audioStartSeconds":59.680083333333336,"audioEndSeconds":63.099125},{"speaker":"B","text":"Goodnight Mark and sorry again for disturbing your peaceful night.","position":16,"audioStartSeconds":63.299125,"audioEndSeconds":67.43804166666666}],"questions":[{"prompt":"What is the primary purpose of Speaker A visiting Speaker B?","options":["To invite him to an early meeting.","To complain about late night television noise.","To borrow a pair of wireless headphones."],"answer":"B","evidenceSentence":3,"evidence":"your television is quite loud through my bedroom ceiling","explanation":"Speaker A đến để phàn nàn rằng tiếng ti vi của người hàng xóm quá lớn làm ảnh hưởng đến phòng ngủ của anh ấy."},{"prompt":"How does Speaker B initially react to the complaint?","options":["He becomes angry and defensive.","He argues that the volume is not high.","He is polite and immediately apologizes."],"answer":"C","evidenceSentence":4,"evidence":"Oh dear I did not realize the volume was up so high.","explanation":"Speaker B tỏ ra lịch sự, nhận lỗi và không hề tỏ thái độ phòng thủ hay tức giận."},{"prompt":"Why does Speaker A need quietness tonight?","options":["He has an early meeting for a project tomorrow.","He wants to watch an action movie.","He suffers from a severe headache."],"answer":"A","evidenceSentence":5,"evidence":"I have an early meeting tomorrow morning because of an important project.","explanation":"Speaker A giải thích rằng anh ấy có một cuộc họp sớm vào sáng hôm sau cho một dự án quan trọng."},{"prompt":"What is the immediate next action Speaker B will take after the conversation?","options":["Go to sleep immediately.","Turn the sound down right away.","Charge the headphones for tomorrow."],"answer":"B","evidenceSentence":8,"evidence":"I will turn the sound down immediately so you can rest.","explanation":"Hành động ngay lập tức tiếp theo của Speaker B là giảm âm lượng xuống ngay để người hàng xóm có thể nghỉ ngơi."},{"prompt":"What permanent solution do they agree upon for future nights?","options":["Speaker B will use wireless headphones after nine pm.","Speaker A will move to a different flat upstairs.","They will turn off all televisions before midnight."],"answer":"A","evidenceSentence":10,"evidence":"Would you like me to wear wireless headphones after nine pm","explanation":"Họ thống nhất giải pháp lâu dài là Speaker B sẽ đeo tai nghe không dây sau chín giờ tối."},{"prompt":"What does Speaker B admit about the headphones?","options":["He lost them somewhere in the flat.","He bought them last week but forgot to use them.","He borrowed them from a friend yesterday."],"answer":"B","evidenceSentence":12,"evidence":"I bought a pair last week but I simply forgot to use them.","explanation":"Speaker B thừa nhận anh đã mua tai nghe vào tuần trước nhưng quên sử dụng."}]}];const cards=[...document.querySelectorAll('article')];let stopping=null,stoppingAudio=null;
    document.addEventListener('play',event=>{if(event.target.tagName!=='AUDIO')return;document.querySelectorAll('audio').forEach(a=>{if(a!==event.target)a.pause()})},true);
    document.querySelectorAll('[data-filter]').forEach(button=>button.onclick=()=>{let count=0;cards.forEach(c=>{c.hidden=button.dataset.filter!=='ALL'&&c.dataset.goal!==button.dataset.filter;if(!c.hidden)count++;else c.querySelector('audio').pause()});document.querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',b===button));document.querySelector('#filter-status').textContent='Đang hiển thị '+count+' bài.'});
    const normal=value=>value.trim().toLowerCase().replace(/\s+/g,' ');
    document.querySelectorAll('[data-check]').forEach(button=>button.onclick=()=>{const i=Number(button.dataset.check);let score=0;lessons[i].questions.forEach((q,n)=>{const value=normal(document.getElementById('answer-'+i+'-'+n).value);if([q.answer,...(q.accepted||[])].some(a=>normal(a)===value))score++});document.getElementById('result-'+i).textContent=score+'/'+lessons[i].questions.length+' câu đúng. Mở phần đáp án để xem giải thích.'});
    document.querySelectorAll('[data-segment]').forEach(button=>button.onclick=async()=>{if(stopping)stopping();const [i,n]=button.dataset.segment.split(',').map(Number),audio=cards[i].querySelector('audio'),s=lessons[i].sentences[n];audio.currentTime=s.audioStartSeconds;const stop=()=>{stopping=null;stoppingAudio=null;audio.removeEventListener('timeupdate',check);audio.pause()},check=()=>{if(audio.currentTime>=s.audioEndSeconds)stop()};stopping=stop;stoppingAudio=audio;audio.addEventListener('timeupdate',check);try{await audio.play()}catch(_){stop();document.getElementById('result-'+i).textContent='Không phát được audio. Hãy dùng nút tải WAV để nghe.'}});
    document.querySelectorAll('audio').forEach(audio=>audio.addEventListener('pause',()=>{if(audio.paused&&stoppingAudio===audio&&stopping)stopping()}));
const authStatus=document.querySelector('#auth-status');
async function initializeAudio(){
 try{
  const response=await fetch('/api/auth/me',{credentials:'same-origin'});
  if(response.status===401){authStatus.hidden=false;authStatus.innerHTML='Đăng nhập để nghe audio. <a href="/login?next=%2Fcatalog%3Fgoal%3DALL">Đăng nhập</a> rồi mở bài từ thư viện bằng nút “Nghe toàn bài & làm câu hỏi”.';return}
  if(!response.ok)throw Error('account');
  document.querySelectorAll('audio').forEach(audio=>{audio.src=audio.dataset.src;audio.preload='none';audio.hidden=false});
  document.querySelectorAll('[data-segment]').forEach(button=>button.disabled=false);
  document.querySelectorAll('a[download]').forEach(link=>link.hidden=false);
 }catch(_){authStatus.hidden=false;authStatus.textContent='Không kiểm tra được đăng nhập. Hãy tải lại trang để thử lại.'}
}
initializeAudio();
